import { ISO3_SHORT_NAME, NAME_ALIAS_TO_ISO3 } from './country-aliases';

const normalize = (s: string): string => s.toLowerCase().replace(/[^a-z0-9]/g, '');

/**
 * Resolve any SDK-supplied country value to an ISO-3 code (matches the bundled geometry).
 *
 * Accepts ISO-3 ("USA"), ISO-2 ("US"), the formal ISO name ("United States of America"), and the
 * everyday short names people actually set ("United States", "Taiwan", "Turkey") via
 * {@link NAME_ALIAS_TO_ISO3}. Punctuation, case and spacing are irrelevant — "United-States",
 * "united states" and "UNITED_STATES" all normalize to the same key. Returns null if unknown, and
 * the caller rolls that into an "Unknown" bucket.
 */
export function toIso3(country: string | null | undefined): string | null {
  if (!country) return null;
  const raw = country.trim();
  if (!raw) return null;
  const upper = raw.toUpperCase();
  if (upper.length === 3 && ISO3_NAME[upper]) return upper;
  if (upper.length === 2 && ISO2_TO_ISO3[upper]) return ISO2_TO_ISO3[upper];
  const n = normalize(raw);
  // Generated ISO names first, hand-maintained aliases second: the alias list exists to ADD the
  // everyday spellings, never to override what ISO already says.
  return NAME_TO_ISO3[n] ?? NAME_ALIAS_TO_ISO3[n] ?? null;
}

/**
 * Human-readable country name for an ISO-3 code — the short form where the formal ISO name reads
 * badly in a table ("United States", not "United States of America").
 */
export function iso3Name(iso3: string): string {
  return ISO3_SHORT_NAME[iso3] ?? ISO3_NAME[iso3] ?? iso3;
}
